// Auto-generated embedded assets (base64) — no external files needed
const ASSETS = {
  roomAdoptme: "data:image/jpeg;base64,",
  roomHm: "data:image/jpeg;base64,",
  roomKrispy: "data:image/jpeg;base64,",
  roomOffice: "data:image/jpeg;base64,",
  roomSmclark: "data:image/jpeg;base64,",
  spriteIdle: "data:image/jpeg;base64,",
  spriteJumpscare: "data:image/jpeg;base64,",
  titleCalm: "data:image/jpeg;base64,",
  titleOpenmouth: "data:image/jpeg;base64,",
  back: "data:image/png;base64,",
  tablet: "data:image/png;base64,",
  phone: "data:image/jpeg;base64,",
  map: "data:image/png;base64,",
  transition: "data:image/webp;base64,",
};/* =========================================================
   5 NIGHTS AT NASHA'S — game logic
   ========================================================= */

const GAME_LENGTH_SEC = 5 * 60;      // survive 5 minutes
const SANITY_DRAIN_PER_SEC = 100 / GAME_LENGTH_SEC; // passive drain to hit 0 right at 5:00
const CALL_REFILL_AMOUNT = 28;       // sanity gained per call
const CALL_COOLDOWN_SEC = 12;        // can't spam Brent
const CALL_DURATION_MS = 3600;       // how long the call sequence takes

const rooms = {
  adoptme: { label: "CAM 01 — ADOPT ME ROOM", img: ASSETS.roomAdoptme },
  hm:      { label: "CAM 02 — H&M ROOM",       img: ASSETS.roomHm },
  krispy:  { label: "CAM 03 — KRISPY KREME",   img: ASSETS.roomKrispy },
  smclark: { label: "CAM 04 — SM CLARK ROOM",  img: ASSETS.roomSmclark },
};

/* ---------------- assign embedded images to DOM on load ---------------- */
function wireUpImages() {
  document.getElementById('title-art').src = ASSETS.titleCalm;
  document.getElementById('office-bg').src = ASSETS.roomOffice;
  document.getElementById('office-scare').src = ASSETS.spriteIdle;
  document.getElementById('tablet-icon').src = ASSETS.tablet;
  document.getElementById('phone-icon').src = ASSETS.phone;
  document.getElementById('transition-img').src = ASSETS.transition;
  document.getElementById('map-img').src = ASSETS.map;
  document.getElementById('map-back-icon').src = ASSETS.back;
  document.getElementById('nasha-peek').src = ASSETS.spriteIdle;
  document.getElementById('feed-back-icon').src = ASSETS.back;
  document.getElementById('jumpscare-img').src = ASSETS.spriteJumpscare;
}
wireUpImages();

/* ---------------- state ---------------- */
let sanity = 100;
let timeLeft = GAME_LENGTH_SEC;
let gameTicking = false;
let tickInterval = null;
let lastCallTime = -9999;
let gameStartMs = 0;

/* ---------------- dom refs ---------------- */
const screens = {
  title: document.getElementById('title-screen'),
  howto: document.getElementById('howto-screen'),
  game: document.getElementById('game-screen'),
  jumpscare: document.getElementById('jumpscare-screen'),
  gameover: document.getElementById('gameover-screen'),
  victory: document.getElementById('victory-screen'),
};

const sanityVal = document.getElementById('sanity-val');
const sanityFill = document.getElementById('sanity-fill');
const timerVal = document.getElementById('timer-val');
const officeScare = document.getElementById('office-scare');

const tabletBtn = document.getElementById('tablet-btn');
const phoneBtn = document.getElementById('phone-btn');
const callBox = document.getElementById('call-box');
const callLine = document.getElementById('call-line');

const transitionOverlay = document.getElementById('transition-overlay');
const mapScreen = document.getElementById('map-screen');
const feedScreen = document.getElementById('feed-screen');
const feedBg = document.getElementById('feed-bg');
const feedRoomLabel = document.getElementById('feed-room-label');
const nashaPeek = document.getElementById('nasha-peek');
const mapBackBtn = document.getElementById('map-back-btn');
const feedBackBtn = document.getElementById('feed-back-btn');

function showScreen(name) {
  Object.values(screens).forEach(s => s.classList.remove('active'));
  screens[name].classList.add('active');
}

/* =========================================================
   PROCEDURAL AUDIO — no external files needed
   ========================================================= */
let actx = null;
let droneNodes = [];
let droneGain = null;

function ensureAudio() {
  if (!actx) {
    actx = new (window.AudioContext || window.webkitAudioContext)();
  }
  if (actx.state === 'suspended') actx.resume();
}

function startDrone() {
  ensureAudio();
  stopDrone();
  droneGain = actx.createGain();
  droneGain.gain.value = 0.05;
  droneGain.connect(actx.destination);

  // two slightly detuned low oscillators for an unsettling drone
  const freqs = [55, 58.5, 110];
  freqs.forEach((f, i) => {
    const osc = actx.createOscillator();
    osc.type = i === 2 ? 'sine' : 'sawtooth';
    osc.frequency.value = f;
    const g = actx.createGain();
    g.gain.value = i === 2 ? 0.03 : 0.06;
    const filt = actx.createBiquadFilter();
    filt.type = 'lowpass';
    filt.frequency.value = 220;
    osc.connect(filt);
    filt.connect(g);
    g.connect(droneGain);
    osc.start();
    droneNodes.push(osc);
  });

  // slow LFO wobble on master drone gain for creeping unease
  const lfo = actx.createOscillator();
  lfo.frequency.value = 0.07;
  const lfoGain = actx.createGain();
  lfoGain.gain.value = 0.025;
  lfo.connect(lfoGain);
  lfoGain.connect(droneGain.gain);
  lfo.start();
  droneNodes.push(lfo);

  scheduleRandomCreak();
}

function stopDrone() {
  droneNodes.forEach(n => { try { n.stop(); } catch (e) {} });
  droneNodes = [];
  if (droneGain) { try { droneGain.disconnect(); } catch(e) {} }
}

let creakTimeout = null;
function scheduleRandomCreak() {
  clearTimeout(creakTimeout);
  if (!gameTicking) return;
  const delay = 6000 + Math.random() * 9000;
  creakTimeout = setTimeout(() => {
    playCreak();
    scheduleRandomCreak();
  }, delay);
}

function playCreak() {
  if (!actx) return;
  const osc = actx.createOscillator();
  osc.type = 'triangle';
  const g = actx.createGain();
  const startF = 200 + Math.random() * 150;
  osc.frequency.setValueAtTime(startF, actx.currentTime);
  osc.frequency.exponentialRampToValueAtTime(startF * (0.4 + Math.random()*0.3), actx.currentTime + 0.8);
  g.gain.setValueAtTime(0.0001, actx.currentTime);
  g.gain.linearRampToValueAtTime(0.05, actx.currentTime + 0.05);
  g.gain.exponentialRampToValueAtTime(0.0001, actx.currentTime + 0.9);
  osc.connect(g);
  g.connect(actx.destination);
  osc.start();
  osc.stop(actx.currentTime + 1);
}

function playClick() {
  if (!actx) return;
  const osc = actx.createOscillator();
  const g = actx.createGain();
  osc.type = 'square';
  osc.frequency.value = 900;
  g.gain.setValueAtTime(0.04, actx.currentTime);
  g.gain.exponentialRampToValueAtTime(0.0001, actx.currentTime + 0.08);
  osc.connect(g); g.connect(actx.destination);
  osc.start(); osc.stop(actx.currentTime + 0.08);
}

function playStatic(durationMs) {
  if (!actx) return () => {};
  const bufferSize = actx.sampleRate * 2;
  const buffer = actx.createBuffer(1, bufferSize, actx.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < bufferSize; i++) data[i] = (Math.random() * 2 - 1) * 0.3;
  const noise = actx.createBufferSource();
  noise.buffer = buffer;
  noise.loop = true;
  const g = actx.createGain();
  g.gain.value = 0.05;
  noise.connect(g); g.connect(actx.destination);
  noise.start();
  if (durationMs) setTimeout(() => { try { noise.stop(); } catch(e) {} }, durationMs);
  return () => { try { noise.stop(); } catch (e) {} };
}

function playPhoneRing() {
  if (!actx) return;
  const now = actx.currentTime;
  [0, 0.5].forEach(offset => {
    const osc1 = actx.createOscillator();
    const osc2 = actx.createOscillator();
    const g = actx.createGain();
    osc1.frequency.value = 480;
    osc2.frequency.value = 620;
    g.gain.setValueAtTime(0.0001, now + offset);
    g.gain.linearRampToValueAtTime(0.05, now + offset + 0.05);
    g.gain.linearRampToValueAtTime(0.0001, now + offset + 0.38);
    osc1.connect(g); osc2.connect(g); g.connect(actx.destination);
    osc1.start(now + offset); osc2.start(now + offset);
    osc1.stop(now + offset + 0.4); osc2.stop(now + offset + 0.4);
  });
}

function playSanityChime() {
  if (!actx) return;
  const notes = [660, 880];
  notes.forEach((f, i) => {
    const osc = actx.createOscillator();
    const g = actx.createGain();
    osc.type = 'sine';
    osc.frequency.value = f;
    const t = actx.currentTime + i * 0.09;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(0.06, t + 0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.35);
    osc.connect(g); g.connect(actx.destination);
    osc.start(t); osc.stop(t + 0.4);
  });
}

function playJumpscareStinger() {
  ensureAudio();
  const now = actx.currentTime;
  // harsh noise burst
  const bufferSize = actx.sampleRate * 1;
  const buffer = actx.createBuffer(1, bufferSize, actx.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < bufferSize; i++) data[i] = (Math.random() * 2 - 1);
  const noise = actx.createBufferSource();
  noise.buffer = buffer;
  const noiseGain = actx.createGain();
  noiseGain.gain.setValueAtTime(0.5, now);
  noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.9);
  noise.connect(noiseGain); noiseGain.connect(actx.destination);
  noise.start(now); noise.stop(now + 1);

  // dissonant stab
  [220, 233, 466].forEach(f => {
    const osc = actx.createOscillator();
    const g = actx.createGain();
    osc.type = 'sawtooth';
    osc.frequency.value = f;
    g.gain.setValueAtTime(0.25, now);
    g.gain.exponentialRampToValueAtTime(0.001, now + 1.1);
    osc.connect(g); g.connect(actx.destination);
    osc.start(now); osc.stop(now + 1.1);
  });
}

/* =========================================================
   GAME FLOW
   ========================================================= */
function resetState() {
  sanity = 100;
  timeLeft = GAME_LENGTH_SEC;
  lastCallTime = -9999;
  updateHud();
  callBox.classList.add('hidden');
  officeScare.classList.add('hidden');
  officeScare.classList.remove('flash');
  mapScreen.classList.add('hidden');
  feedScreen.classList.add('hidden');
}

function updateHud() {
  sanityVal.textContent = Math.max(0, Math.round(sanity));
  sanityFill.style.width = Math.max(0, sanity) + '%';
  const green = [111,174,74], red = [176,20,27];
  const t = 1 - sanity / 100;
  const mix = green.map((c, i) => Math.round(c + (red[i] - c) * t));
  sanityFill.style.background = `rgb(${mix[0]},${mix[1]},${mix[2]})`;

  const m = Math.floor(Math.max(0,timeLeft) / 60);
  const s = Math.floor(Math.max(0,timeLeft) % 60);
  timerVal.textContent = `${m}:${s.toString().padStart(2,'0')}`;
}

function startGame() {
  ensureAudio();
  resetState();
  showScreen('game');
  document.getElementById('game-screen').classList.add('active');
  gameTicking = true;
  startDrone();
  clearInterval(tickInterval);
  tickInterval = setInterval(tick, 100);
}

function tick() {
  if (!gameTicking) return;
  timeLeft -= 0.1;
  sanity -= SANITY_DRAIN_PER_SEC * 0.1;
  if (sanity < 0) sanity = 0;
  updateHud();

  // low-sanity dread: office flicker/peek gets more frequent
  if (sanity < 35 && Math.random() < 0.004) triggerOfficeFlash();

  if (sanity <= 0) {
    triggerLoss();
  } else if (timeLeft <= 0) {
    triggerWin();
  }
}

function triggerOfficeFlash() {
  officeScare.classList.remove('hidden');
  officeScare.classList.add('flash');
  setTimeout(() => officeScare.classList.add('hidden'), 300);
}

function triggerLoss() {
  gameTicking = false;
  clearInterval(tickInterval);
  stopDrone();
  playJumpscareStinger();
  showScreen('jumpscare');
  const img = document.getElementById('jumpscare-img');
  img.style.animation = 'none';
  void img.offsetWidth;
  img.style.animation = '';
  setTimeout(() => showScreen('gameover'), 1600);
}

function triggerWin() {
  gameTicking = false;
  clearInterval(tickInterval);
  stopDrone();
  showScreen('victory');
}

/* ---------------- phone / call brent ---------------- */
const callScript = [
  "*Phone Rings*",
  "*Click*",
  "Nasha: Kiss please!",
  "Brent: Mwah Mwah Mwah!",
  "Nasha: Thank you!",
  "*Call Ends*",
];

let callBusy = false;
function callBrent() {
  if (callBusy || !gameTicking) return;
  const now = performance.now() / 1000;
  if (now - lastCallTime < CALL_COOLDOWN_SEC) return;
  lastCallTime = now;
  callBusy = true;
  ensureAudio();
  playPhoneRing();

  callBox.classList.remove('hidden');
  let i = 0;
  callLine.textContent = callScript[0];
  const stepMs = CALL_DURATION_MS / callScript.length;
  const stepInt = setInterval(() => {
    i++;
    if (i < callScript.length) {
      callLine.textContent = callScript[i];
      if (i === 1) playClick();
    } else {
      clearInterval(stepInt);
      callBox.classList.add('hidden');
      sanity = Math.min(100, sanity + CALL_REFILL_AMOUNT);
      updateHud();
      playSanityChime();
      callBusy = false;
    }
  }, stepMs);
}

/* ---------------- tablet / cctv ---------------- */
function openTablet() {
  if (!gameTicking) return;
  playClick();
  transitionOverlay.classList.remove('hidden');
  const stopStatic = playStatic(650);
  setTimeout(() => {
    transitionOverlay.classList.add('hidden');
    mapScreen.classList.remove('hidden');
  }, 650);
}

function closeTabletToOffice() {
  playClick();
  mapScreen.classList.add('hidden');
  feedScreen.classList.add('hidden');
}

function openFeed(roomKey) {
  playClick();
  const r = rooms[roomKey];
  feedBg.src = r.img;
  feedRoomLabel.textContent = r.label;
  mapScreen.classList.add('hidden');
  feedScreen.classList.remove('hidden');
  nashaPeek.classList.add('hidden');
  nashaPeek.classList.remove('show');

  // flavor scare: random chance she's visible in this feed
  if (Math.random() < 0.35) {
    setTimeout(() => {
      if (feedScreen.classList.contains('hidden')) return;
      nashaPeek.classList.remove('hidden');
      nashaPeek.classList.add('show');
      playCreak();
    }, 500 + Math.random() * 1200);
  }
}

function closeFeedToMap() {
  playClick();
  feedScreen.classList.add('hidden');
  nashaPeek.classList.add('hidden');
  mapScreen.classList.remove('hidden');
}

/* =========================================================
   EVENT WIRING
   ========================================================= */
document.getElementById('start-btn').addEventListener('click', startGame);
document.getElementById('howto-btn').addEventListener('click', () => { ensureAudio(); showScreen('howto'); });
document.getElementById('howto-back-btn').addEventListener('click', () => showScreen('title'));

tabletBtn.addEventListener('click', openTablet);
phoneBtn.addEventListener('click', callBrent);
mapBackBtn.addEventListener('click', closeTabletToOffice);
feedBackBtn.addEventListener('click', closeFeedToMap);

document.querySelectorAll('.cam-hotspot').forEach(btn => {
  btn.addEventListener('click', () => openFeed(btn.dataset.room));
});

document.getElementById('retry-btn').addEventListener('click', startGame);
document.getElementById('menu-btn-1').addEventListener('click', () => showScreen('title'));
document.getElementById('menu-btn-2').addEventListener('click', () => showScreen('title'));

/* ---------------- title screen art flicker ---------------- */
const titleArt = document.getElementById('title-art');
let titleFlickerTimeout = null;
function scheduleTitleFlicker() {
  clearTimeout(titleFlickerTimeout);
  const delay = 4000 + Math.random() * 5000;
  titleFlickerTimeout = setTimeout(() => {
    if (!screens.title.classList.contains('active')) return scheduleTitleFlicker();
    titleArt.src = ASSETS.titleOpenmouth;
    setTimeout(() => {
      titleArt.src = ASSETS.titleCalm;
      scheduleTitleFlicker();
    }, 140);
  }, delay);
}
scheduleTitleFlicker();

showScreen('title');
